def longest_common_subsequence(text1, text2):
    m, n = len(text1), len(text2)
    dp = [0] * (n + 1)
    for i in range(m):
        prev = 0
        for j in range(n):
            temp = dp[j + 1]
            if text1[i] == text2[j]: dp[j + 1] = prev + 1
            else: dp[j + 1] = max(dp[j + 1], dp[j])
