def trie_operations(words, queries):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['#'] = True
    res = []
    for q in queries:
        node = root
        ok = True
        for ch in q:
            if ch not in node:
                ok = False; break
            node = node[ch]
        res.append(ok)
    return res

